(window.BIB_BOOKS=window.BIB_BOOKS||{})["PHP"]={"chapters":[["פולוס וטימותיוס עבדי המשיח ישוע אל כל הקדשים במשיח ישוע אשר הם בפילפי עם הפקידים והשמשים׃","חסד לכם ושלום מאת האלהים אבינו ואדנינו ישוע המשיח׃","אודה לאלהי מדי זכרי אתכם׃","ותמיד בכל תפלותי אתחנן בשמחה בעד כלכם׃","על התחברותכם אל הבשורה למן היום הראשון ועד הנה׃","ובטח אני כי המתחיל בכם המעשה הטוב גם יגמרנו עד יום ישוע המשיח׃","כאשר ראוי לי לחשב ככה על כלכם בעבור שאתי אתכם בלבבי במוסרי ובהצדיקי ובחזקי את הבשורה באשר כלכם חברי בחסד׃","כי האלהים לי לעד אשר לכלכם נכספתי באהבת ישוע המשיח׃","ועל זאת מתפלל אנכי כי תרבה ותגדל אהבתכם בהשכל ובכל דעת׃","למען תבחנו את המבחרות והייתם זכים ובלי מכשול עד יום המשיח׃","מלאים פרי הצדקה על ידי ישוע המשיח לכבוד אלהים ותהלתו׃","והנני מודיע אתכם אחי כי אשר מצאתני היתה אך ליתרון הבשורה׃","עד אשר נגלו מוסרותי במשיח בכל שער המלך ולכל הנשארים׃","ורב האחים באדנינו הוסיפו אמץ במוסרותי והתחזקו יותר בלבבם לדבר את הדבר בלי פחד׃","הן יש מגידים את המשיח מקנאה וריב ויש מגידים בכונה טובה׃","אלה ממריבה מגידים את המשיח לא בלב טהור כי חשבים להוסיף צרה על מוסרי׃","ואלה מאהבה באשר הם ידעים כי נתון אנכי להצדיק את הבשורה׃","אך מה בכך הלא בכל אופן אם בעלילה או באמת יגד המשיח ואני הנני שמח בזאת וגם אשמח׃","כי יודע אני שתהיה לי זאת לישועה בתפלתכם ובעזרת רוח ישוע המשיח׃","ואוחיל ואקוה שלא אבוש בכל דבר כי אם בכל בטחון כאשר מאז כן גם עתה יתגדל המשיח בגופי אם בחיי אם במותי׃","כי המשיח הוא חיי והמות רוח לי׃","אולם אם לחיות בבשר עוד יוסיף לי פרי עמלי אין לי להגיד במה אבחר׃","כי משוך אני מן השנים נפשי אותה להפטר ולהיות עם המשיח כי זה המבחר׃","אבל לעמד עוד בבשר צריך יתר בעבורכם׃","ואני בטח וידע כי אותר ואעמד עם כלכם יחד לאמץ אתכם ולהגדיל שמחת אמונתכם׃","למען תרבה על ידי תהלתכם במשיח ישוע בשובי לבוא אליכם׃","רק חתנהגו כראוי לבשורת המשיח למען אשמע עליכם אם בבואי לראותכם אם בהיותי רחוק כי קימים אתם ברוח אחת ועזרים אתי בנפש אחת להלחם בעד אמונת הבשורה׃","ואינכם חרדים מאומה מפני המתקוממים אשר זאת להם אות לאבדם ולכם לישועתכם ומאת האלהים היא׃","כי נתן לכם בעד המשיח לא לבד להאמין בו כי אם גם להתענות בעדו׃","כי גם לכם המלחמה אשר ראיתם בי ואשר עתה שמעים אתם עלי׃"],["לכן אם יש תוכחה במשיח אם תנחומות האהבה אם התחברות הרוח אם רחמים וחמלה׃","השלימו נא את שמחתי בהיות לכם לב אחד ואהבה אחת ונפש אחת ורצון אחד׃","ולא תעשו דבר בדרך מריבה או כבוד שוא כי אם בשפלות רוח תחשבו איש את רעהו יותר מעצמו׃","כל אחד אל ידאג לאשר לו לבדו כי אם גם לאשר לחברו׃","כי הרוח ההיא אשר היתה במשיח תהי גם בכם׃","אשר אף כי היה בדמות האלהים לא חשב לו לשלל היותו שוה לאלהים׃","כי אם הפשיט את עצמו וילבש דמות עבד וידמה לבני אדם וימצא בתכונתו כבן אדם׃","וישפל את נפשו ויכנע עד מות עד מיתת הצליבה׃","על כן גם האלהים הגביהו מאד ויתן לו שם נעלה על כל שם׃","למען אשר בשם ישוע תכרע כל ברך אשר בשמים ובארץ ומתחת לארץ׃","וכל לשון תודה כי אדון הוא ישוע המשיח לכבוד אלהים האב׃","לכן חביבי כאשר שמעתם לי בכל עת כן לא לבד בהיותי עמכם כי עוד יתר עתה אשר אני רחוק מכם תיגעו בתשועת נפשתיכם ביראה וברעדה׃","כי האלהים הוא הפעל בכם גם לחפץ גם לפעל כפי רצונו׃","עשו כל דבר בלא תלנות ובלא מזמות׃","למען תהיו נקיים וטהורים בני אלהים לא מום בם בתוך דור עקש ופתלתל אשר תאירו ביניהם כמאורת בעולם׃","מחזיקים בדבר החיים לתהלה לי ביום המשיח אשר לא לחנם רצתי ולא לריק יגעתי׃","אבל אם גם אסך על זבח אמונתכם ועבודתה הנני שמח וגם שש עם כלכם׃","וככה שמחו אף אתם ושישו עמדי׃","וקויתי בישוע אדנינו לשלח במהרה אליכם את טימותיוס למען תנוח דעתי בהודע לי דבר מעמדכם׃","כי זולתו אין אתי איש כלבבי אשר בלב שלם ידאג לכם׃","כי כלם את אשר להם ידרשו ולא את אשר לישוע המשיח׃","ואותו ידעתם כי בחון הוא אשר כבן העבד את אביו כן היה אתי בעבודת הבשורה׃","ואתו אקוה לשלח אליכם מהר כאשר אראה מה יהיה לי׃","ובטחתי באדנינו אשר גם אנכי אבוא אליכם במהרה׃","ואחשב מן הצרך לשלח אליכם את אפפרודיטוס אחי ועזרי וחברי בצבא והוא שליחכם ומשרתי בצרכי׃","יען היותו נכסף לכלכם ונעצב מאד על אשר שמעתם כי חלה׃","אמנם חלה חלה וגם נטה למות אבל האלהים רחם עליו ולא עליו בלבד כי גם עלי רחם שלא יבוא עלי יגון על יגון׃","לכן מהרתי לשלחו אליכם למען תראהו ותשובו לשמוח וגם ימעט יגוני׃","על כן קבלהו באדנינו בכל שמחה והוקירוט אנשים כמהו׃","כי בעבור מעשה המשיח הגיע עד מות ותקל נפשו בעיניו למען ימלא את אשר חסרתם בשרתכם אותי׃"],["ובכן אחי שמחו באדנינו הן לכתב ולשנות כזאת אליכם עלי איננו לטרח ולכם הוא לחזוק׃","הזהרו מן הכלבים הזהרו מן הפעלים הרעים הזהרו מן החתוך׃","כי אנחנו בני המילה העבדים את האלהים ברוח ומתפארים במשיח ישוע ואיננו בטחים בבשר׃","אף כי גם לי יש לבטח בבשר ואם יחשב איש שיוכל לבטח בבשר הנה אני יותר ממנו׃","אשר אני נמול בן שמונת ימים מבני ישראל משבט בנימין עברי מן העברים׃","לפי התורה פרוש בקנאתי רדף את העדה ולפי צדקת התורה בלי שמץ׃","אך היתרנות האלה כלן חשבתי לי לחסרנות למען המשיח׃","וגם עודני חשב את כלן לחסרון לעמת מעלת ידיעת ישוע המשיח אדני אשר בעבורו חסרתי את נפשי מכל אלה ואחשבם לסחי להרויח את המשיח ולהמצא בו׃","ולא תהיה לי צדקתי מתוך התורה כי אם באמונת המשיח הצדקה הבאה מאת האלהים באמונה׃","לדעת אתו ואת גבורת תחיתו והתחברות ענוייו ולהדמות למותו׃","להגיע אם אוכל אל תחית המתים׃","לא כאלו השגתי כבר או כאלו השלמתי אבל ארדף אולי אשיג כאשר גם השיגני המשיח ישוע׃","אחי אינני חשב כי כבר השגתי אך אחת דברתי כי שכח אני את אשר מאחרי ואשתטח אל אשר לפני׃","וארדף את מטרת שכר הנצחון אשר הוא בקריאה של מעלה מאת האלהים במשיח ישוע׃","לכן מי שהוא שלם בנו כן יחשב ואם תחשבו מחשבה אחרת גם זאת יגלה לכם האלהים׃","רק נתהלכה באשר הגענו עדיה במעגל אחד יבלב אחד׃","אחי היו חברים להלכים אחרי והביטו אל המתהלכים כן כאשר אנחנו מופת לכם׃","כי רבים המתהלכים כן כאשר אנחנו מופת לכם׃","כי רבים המתהלכים אשר עליהם אמרתי לכם פעמים הרבה ועתה גם בבכי אני אמר כי הם איבי צלב המשיח׃","אשר אחריתם האבדון אשר כרסם אלהיהם וכבודם בבשתם וקרבם הבלי חלד׃","כי אזרחותנו בשמים היא ומשם מחכים אנחנו למושיענו אדנינו ישוע המשיח׃ [ (Philippians 3:22) אשר יחליף את גוף שפלותנו להיותו דומה לגוף כבודו כפי כח יכלתו לכבש הכל תחתיו׃ ]"],["ועתה אחי החביבים והחמודים שמחתי ועטרת ראשי עמדו נא כן באדנינו חביבי׃","את אבהודיה אני מזהיר ואת סונטיכי אני מזהיר להיות לב אחד באדנינו׃","ואתה חברי הנצמד לי באמת אף ממך אני מבקש להיות להן לעזר אשר יגעו עמדי על הבשורה עם קלימיס ועם שאר תמכי אשר שמותם יחד בספר החיים׃","שמחו באדנינו בכל עת ועוד הפעם אמר אני שמחו׃","ענות רוחכם תודע לכל איש קרב הוא האדון׃","אל תדאגו כי אם בתפלה ובתחנונים עם תודה תודיעו בכל דבר את משאלותיכם לאלהינו׃","ושלום אלהים הנשגב מכל שכל ינצר את לבבכם ואת מחשבותיכם במשיח ישוע׃","ובכן אחי כל אשר הוא אמת ונכבד וישר וטהור ונעים ואשר שמעו טוב כל מעשה צדק כל מעשה שבח על אלה תשימו לבבכם׃","אשר למדתם וקבלתם ושמעתם וראיתם בי את אלה תעשו ואלהי השלום יהיה עמכם׃","ואני שמחתי מאד באדנינו כי עתה הפעם החלפתם כח להשגיח עלי וגם משגיחים הייתם עד כה אך לא עלתה בידכם׃","ולא ממחסור אדבר כן כי למדתי להסתפק במה שיש לי׃","ידעתי לענות אף ידעתי להותיר מחנך אני בכל ענין ואופן הן לשבע הן לרעב הן להותיר הן לחסר׃","כל זאת אוכל בעזרת המשיח הנותן כח בקרבי׃","אבל היטבתם לעשות בהתחברכם אלי בצרתי׃","וידעתם גם אתם פילפיים כי בראשית הבשורה כצאתי ממקדוניא לא התחברה לי אחת מן הקהלות בעשק משא ומתן כי אם אתם בלבד׃","כי גם בתסלוניקי שלחתם לי את צרכי פעם ושתים׃","לא שאבקש את המתן אך אבקש הפרי אשר ירבה בחשבנכם׃","ואני קבלתי את הכל ויש לי די והותר ואני נמלאתי ריח ניחח בקבלי מידי אפפרודיטוס את כל אשר שלחתם זבח ערב ורצוי לאלהים׃","ואלהי הוא ימלא את כל צרככם כעשר כבודו במשיח ישוע׃","ולאלהים אבינו הכבוד לעולמי עולמים אמן׃","שאלו לשלום כל קדוש במשיח ישוע האחים אשר עמדי שאלים לשלומכם׃","כל הקדשים שאלים לשלומכם וביותר אלה אשר מבית הקיסר׃","חסד ישוע המשיח אדנינו עם כלכם אמן׃"]]};
